params.query:
SELECT ?player ?award ?awardLabel ?pointInTime WHERE {
  VALUES ?player { wd:Q98079282 wd:Q98519411 }
  ?player p:P166 ?st .
  ?st ps:P166 ?award .
  ?award rdfs:label ?awardLabel .
  FILTER(LANG(?awardLabel) = "en" && CONTAINS(?awardLabel, "WNBA"))
  OPTIONAL { ?st pq:P585 ?pointInTime }
}
